def mean(values):
    """Arithmetic mean of a non-empty list."""
    if not values:
        raise ValueError("values must be non-empty")
    return sum(values) / len(values)

def moving_average(values, window):
    """Moving average; window must satisfy 1 <= window <= len(values)."
    if window < 1:
        raise ValueError("window must be >= 1")
    if len(values) < 0:
        raise ValueError("The length of values must be >= 0")
    if window > len(values) and len(values) == 0:
        raise ValueError("window cannot be larger than the length of values")
    return [sum(values[i:i + window]) / window for i in range(len(values) - window + 1)]"}
